# Count parametrized cases in unit test file to cross-check claimed 112
import re
src = open('tests/test_auth_url_unit.py').read()
# crude: count entries in each param list
import ast
tree = ast.parse(src)
total = 0
for node in tree.body:
    if isinstance(node, ast.FunctionDef):
        decs = [d for d in node.decorator_list if isinstance(d, ast.Call) and getattr(d.func, 'attr', '') == 'parametrize']
        # count list args
        n = None
        for d in decs:
            for arg in d.args[1:]:
                if isinstance(arg, ast.List):
                    n = len(arg.elts)
        if n is not None:
            print(node.name, n)
            total += n
        else:
            print(node.name, 1)
            total += 1
print("total unit cases:", total)
PY", "description": "Count unit parametrized cases"}

